#pragma once
template<class Check> void directionalBoostChecks(Check check){
 using namespace ff3Assist;
 check(directionalBoostReady(10,10.02,14,1,{43,-8,0})&&directionalBoostReady(10,10.14,16,0,{43,0,0}),"native dive propulsion can start airborne or during a native slide without any ball argument");
 check(!directionalBoostReady(10,10.02,8,0,{20,0,0})&&!directionalBoostReady(10,10.7,14,1,{43,0,0}),"ordinary walking and an expired key press do not start propulsion");
 check(directionalBoostReady(10,10.008,3,0,{43,12,0},true)&&directionalBoostReady(10,10.016,5,0,{43,-5,0},true),"Boost starts on jumping or freefall takeoff before ragdoll replication");
 check(!directionalBoostReady(10,10.3,14,1,{43,0,0},false),"a missed takeoff cannot become a delayed touchdown boost");
 check(directionalBoostContinues(3,0,true)&&directionalBoostContinues(5,0,true)&&!directionalBoostContinues(8,0,false),"active airborne propulsion survives the delayed ragdoll flag and stops on ordinary ground");
 for(double angle:{0.,.7,1.7,3.14,4.2})for(double speed:{20.,43.,65.})for(double budget:{1.,7.,20.,30.}){
  Vec direction{std::cos(angle),0,std::sin(angle)},velocity=direction*speed;velocity.y=-17;DirectionalBoost boost;check(boost.begin(velocity,10,budget),"forward propulsion starts with only velocity, time and its extra-distance budget");double travel=0;bool complete=false;
  for(int i=0;i<100;++i){const double time=10+i*.008;auto command=boost.sample(velocity,time);check(command.valid&&command.velocity.y==-17,"directional propulsion preserves vertical movement");if(command.complete){complete=true;check(ff3qb::length(flat(command.velocity))<=speed+.001,"completion removes only the extra propulsion");break;}const auto horizontal=flat(command.velocity);check(ff3qb::dot(horizontal,direction)>=0&&ff3qb::length(horizontal-direction*ff3qb::dot(horizontal,direction))<1e-6&&ff3qb::length(horizontal)<=120.001,"manual Boost stays on the original dive ray and respects the horizontal speed cap");travel+=std::max(0.,ff3qb::dot(horizontal,direction)-speed)*.008;velocity=command.velocity;}
  check(complete&&travel<=budget+.2&&travel>=std::max(0.,budget-.8),"extra travel stays consistent across native speeds and directions without target-distance dependence");
 }
 for(double angle:{-3.,-2.,-1.,0.,1.,2.,3.}){Vec velocity{std::sin(angle)*43,5,std::cos(angle)*43};const auto safe=forwardDiveVelocity(velocity,{0,0,1});check(safe.z>=-1e-6&&safe.y==5&&ff3qb::length(flat(safe))<=43.001,"the velocity output guard never commands backwards movement even for an opposing input velocity");}
 DirectionalBoost fixed;check(fixed.begin({43,8,0},10,7),"independent-direction fixture starts");auto command=fixed.sample({0,8,-43},10.04,false);check(command.velocity.x>43&&std::abs(command.velocity.z)<1e-6,"Boost does not choose a new direction from an unrelated target or current sideways velocity");
 ff3Play::Scene scene;scene.valid=scene.focused=true;scene.typing=scene.menu=false;scene.pid=1;scene.model=2;scene.own=3;scene.player=4;scene.at=10;scene.head={0,10,0};scene.rootPosition={0,8,0};scene.groundY=0;scene.velocity={0,0,25};scene.worldGravity=196.2;ContactReach hand{{},1.25,true};ff3qb::BallObservation ball{100,{0,10,10},{},196.2,false,99,true};
 auto onPath=directionalSmartTarget(scene,ball,10,40,8,{0,0,1},25,hand);check(onPath.valid&&onPath.requiredExtra>0&&onPath.requiredExtra<=8,"Smart distance finds a timed catch on the existing dive ray");ball.position.x=10;check(!directionalSmartTarget(scene,ball,10,40,8,{0,0,1},25,hand).valid,"Smart Boost skips off-path balls rather than homing sideways toward them");
 {DirectionalBoost smart;check(smart.begin(scene.velocity,10,onPath.requiredExtra,onPath.eta),"directional Smart mode starts with the computed extra distance and arrival time");Vec position=scene.rootPosition,velocity=scene.velocity;auto first=smart.sample(velocity,10);velocity=first.velocity;double elapsed=0;while(elapsed<onPath.eta){const double dt=std::min(.004,onPath.eta-elapsed);position=position+flat(velocity)*dt;elapsed+=dt;auto command=smart.sample(velocity,10+elapsed);check(command.valid&&std::abs(command.velocity.x)<1e-6,"Smart distance changes speed without adding any sideways homing component");velocity=command.velocity;if(command.complete)break;}check(distance(position,onPath.point)<=hand.radius&&smart.spent<=8.05,"directional Smart propulsion reaches an on-path contact within its distance limit");}
}
